 useEffect(()=>{if(game?.phase==='event'&&game.pendingScenario&&scenarioCards.find(c=>c.id===game.pendingScenario)?.effect==='schools')setSchoolChoices(destinations.filter(d=>d.type==='education').slice(0,game.players.length).map(d=>d.hub))},[game?.pendingScenario,game?.players.length]);
 useEffect(()=>{if(!game||!game.players[game.turn]?.bot||!['cones','roll','move','question','destination-choice','event','hand','card-reveal','relocate'].includes(game.phase))return;const t=setTimeout(()=>{if(session)request('bot');else setGame(old=>{if(!old)return old;let g=structuredClone(old);botTurn(g,blackDotLocationIds);return g})},1100);return()=>clearTimeout(t)},[game,session]);
 function act(action:string,to?:string,correct?:boolean,scenarioId?:string){if(session){request(action,{to,correct,scenarioId,...(action==='cone'||action==='begin-cone-move'||action==='pass-construction'?{edge:to}:{}),...(action==='relocate-cone'?{targetEdge:to}:{})});return;}if(!game)return;try{const g=structuredClone(game);if(action==='roll')roll(g);if(action==='move')move(g,to!);if(action==='end')endTurn(g);if(action==='answer')answer(g,!!correct);if(action==='cone')placeCone(g,to!,blackDotLocationIds);if(action==='begin-cone-move')beginConeMove(g,to!);if(action==='pass-construction')passConstruction(g,to!,scenarioId);if(action==='dismiss-construction')dismissConstructionChoice(g);if(action==='stay-road')stayOnRoad(g);if(action==='relocate-cone')relocateCone(g,to!,blackDotLocationIds);setGame(g)}catch(e){setError(String(e))}}
 function scenarioAction(action:string,value?:string,road?:Road){if(session){request(action,{scenarioId:action==='resolve-scenario'?undefined:value,choice:action==='resolve-scenario'?value:undefined,road});return}if(!game)return;try{const g=structuredClone(game);if(action==='switch-road')changeRoad(g,road!);if(action==='play-change-road')playChangeRoadCard(g,value!,road!);if(action==='play-construction-pass')playConstructionPass(g,value!);if(action==='discard-held')discardHeldCard(g,value!);if(action==='resolve-scenario')resolveScenario(g,value,blackDotLocationIds);if(action==='cancel-scenario')cancelScenario(g,value!);if(action==='expire-question')answer(g,false);setGame(g)}catch(e){setError(String(e))}}
 function destinationChoice(play:boolean){if(session){request('choose-destination',{play});return}if(!game)return;try{const g=structuredClone(game);chooseDestination(g,play);setGame(g)}catch(e){setError(String(e))}}
 function drawnCardAction(action:'keep-card-private'|'show-card',id:string,recipientSeat?:number){if(session){request(action,{scenarioId:id,recipientSeat});return}if(!game)return;try{const g=structuredClone(game);if(action==='keep-card-private')keepCardPrivate(g,id);else if(recipientSeat!==undefined)showCardToPlayer(g,id,recipientSeat);setGame(g)}catch(e){setError(String(e))}}
 function dismissReveal(revealId:string){if(session){request('dismiss-card-reveal',{revealId});return}if(!game)return;try{const g=structuredClone(game);dismissCardReveal(g,revealId,session?.seat??g.turn);setGame(g)}catch(e){setError(String(e))}}
 function askRoadChange(to:string,road:Road){if(session){request('begin-road-change',{to,road});return}if(!game)return;try{const g=structuredClone(game);beginRoadChange(g,to,road);setGame(g)}catch(e){setError(String(e))}}
 function decideRoadChange(confirm:boolean){if(session){request('confirm-road-change',{confirm});return}if(!game)return;try{const g=structuredClone(game);confirmRoadChange(g,confirm);setGame(g)}catch(e){setError(String(e))}}
 function changePlayerCount(h:number,b:number){setHumans(h);setBots(b);const total=h+b;setStopMix(m=>({easy:Math.min(m.easy,Math.floor(32/total)),hard:Math.min(m.hard,Math.floor(40/total)),education:Math.min(m.education,Math.floor(8/total))}))}
